"""One-glyph webfaces that give U+02BB (the Hawaiian ʻokina) a real glyph.

GENERATED by tools/build_okina_font.py — do not hand-edit.

Manrope, Poppins and Open Sans do not encode U+02BB, so an ʻokina set in
any of them silently falls back to the OS UI font — visibly off-weight next
to its neighbours, on screen and in the PDF. These faces re-encode each
family's own U+2018 outline at U+02BB, so the mark is the one that family's
designer drew. The text keeps the correct character: no quote-mark
substitution, which Hawaiian orthography treats as an error.

Usage, from a project renderer:

    from docsync.okina import OKINA_FACES, okinafy

    # emit OKINA_FACES once inside the page's <style>, then either write
    # the stacks yourself:
    #     body { font-family: OkinaManrope, Manrope, system-ui, sans-serif }
    # or, for CSS inherited from a page you did not author:
    #     STYLE = okinafy(STYLE)

The Okina* family MUST come first in the stack. Its unicode-range keeps it
from claiming any character but the ʻokina, and a family listed after one
that already claims U+02BB never gets consulted — which is why the tempting
shortcut of adding these faces to the REAL families does not work: Google's
own latin face declares U+02BB in its unicode-range without shipping the
glyph, wins the match, and falls back. Verified, not assumed.

Manrope (c) 2018 The Manrope Project Authors; Poppins (c) 2020 The Poppins
Project Authors; Open Sans (c) 2020 The Open Sans Project Authors.
All SIL OFL 1.1, no Reserved Font Name.
"""
import re

# source family (lowercased) -> the one-glyph family that fronts it
OKINA_FOR = {
    "manrope": "OkinaManrope",
    "poppins": "OkinaPoppins",
    "open sans": "OkinaOpenSans",
}

OKINA_FACES = r'''
  @font-face { font-family:'OkinaManrope'; font-weight:200 800;
    font-style:normal; font-display:block;
    src:url(data:font/woff2;base64,) format('woff2');
    unicode-range:U+02BB; }
  @font-face { font-family:'OkinaPoppins'; font-weight:300;
    font-style:normal; font-display:block;
    src:url(data:font/woff2;base64,) format('woff2');
    unicode-range:U+02BB; }
  @font-face { font-family:'OkinaPoppins'; font-weight:400;
    font-style:normal; font-display:block;
    src:url(data:font/woff2;base64,) format('woff2');
    unicode-range:U+02BB; }
  @font-face { font-family:'OkinaPoppins'; font-weight:500;
    font-style:normal; font-display:block;
    src:url(data:font/woff2;base64,) format('woff2');
    unicode-range:U+02BB; }
  @font-face { font-family:'OkinaPoppins'; font-weight:600;
    font-style:normal; font-display:block;
    src:url(data:font/woff2;base64,) format('woff2');
    unicode-range:U+02BB; }
  @font-face { font-family:'OkinaPoppins'; font-weight:700;
    font-style:normal; font-display:block;
    src:url(data:font/woff2;base64,) format('woff2');
    unicode-range:U+02BB; }
  @font-face { font-family:'OkinaOpenSans'; font-weight:300 800;
    font-style:normal; font-display:block;
    src:url(data:font/woff2;base64,) format('woff2');
    unicode-range:U+02BB; }
'''


_FAMILY = r"""(?P<q>['"]?)(?P<fam>Manrope|Poppins|Open\s+Sans)(?P=q)"""

# `font-family: 'Poppins', sans-serif`
_STACK = re.compile(r"font-family\s*:\s*" + _FAMILY, re.I)

# `font: 500 13px/1.4 'Poppins', sans-serif` — the shorthand hides the family
# behind the size/line-height, and missing it is not academic: one such rule on
# a position:fixed announcement bar put a fallback ʻokina on all 11 PDF pages.
# The (?!Okina) guard keeps the pass idempotent, since here the inserted name
# lands in the middle of the value rather than directly after the colon.
_SHORT = re.compile(r"\bfont\s*:\s*(?:(?!Okina)[^;}\"'])*?" + _FAMILY, re.I)


def okinafy(css: str) -> str:
    """Prepend each font's Okina* twin to every stack in `css` that names it.

    Handles inline `style=` attributes as happily as a stylesheet — it is only
    looking at declarations. Safe to run twice: an already-prefixed stack no
    longer matches.
    """
    def lead(m: "re.Match[str]") -> str:
        return OKINA_FOR[" ".join(m.group("fam").lower().split())] + ", "

    css = _STACK.sub(lambda m: "font-family:" + lead(m)
                     + m.group(0).split(":", 1)[1].lstrip(), css)
    return _SHORT.sub(lambda m: _insert(m, lead(m)), css)


def _insert(m: "re.Match[str]", lead: str) -> str:
    """Splice `lead` in front of the family name inside a matched declaration."""
    at = m.group(0).rindex(m.group("fam")) - len(m.group("q"))
    return m.group(0)[:at] + lead + m.group(0)[at:]
